from collections import defaultdict

from libcat.util.dates import years_of


class _SetIndex:
    def __init__(self):
        self._buckets = defaultdict(set)

    def _keys(self, record):
        raise NotImplementedError

    def add(self, record):
        for key in self._keys(record):
            self._buckets[key].add(record.id)

    def remove(self, record):
        for key in self._keys(record):
            bucket = self._buckets.get(key)
            if bucket is not None:
                bucket.discard(record.id)
                if not bucket:
                    del self._buckets[key]

    def ids_for(self, key):
        return set(self._buckets.get(key, ()))

    def counts(self):
        return {k: len(v) for k, v in self._buckets.items()}

    def buckets(self):
        return {k: set(v) for k, v in self._buckets.items()}


class YearIndex(_SetIndex):
    def _keys(self, record):
        return years_of(record.date)

    def ids_between(self, year_from=None, year_to=None):
        out = set()
        for year, ids in self._buckets.items():
            if year_from is not None and year < year_from:
                continue
            if year_to is not None and year > year_to:
                continue
            out |= ids
        return out


class SubjectIndex(_SetIndex):
    def _keys(self, record):
        return set(record.subjects)
"""Publisher feed format.

A feed is a sequence of records separated by blank lines. Each line is
`key: value`. Lines starting with `#` are comments. A key may repeat inside
one record (several creators, several subjects, ...): repeated keys are kept
in order as a list, a key that appears once stays a plain string.
"""


def parse_feed(text):
    records, current = [], {}
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if line.startswith("#"):
            continue
        if not line:
            if current:
                records.append(current)
                current = {}
            continue
        if ":" not in line:
            raise ValueError(f"line {lineno}: expected 'key: value'")
        key, value = line.split(":", 1)
        key, value = key.strip().lower(), value.strip()
        if key in current:
            existing = current[key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                current[key] = [existing, value]
        else:
            current[key] = value
    if current:
        records.append(current)
    return records


def as_list(value):
    if value is None:
        return []
    if isinstance(value, list):
        return list(value)
    return [value]


def first(value):
    if isinstance(value, list):
        return value[0] if value else None
    return value
"""Publisher feed ingestion."""
from libcat.models import Record
from libcat.util.feed_format import as_list, first, parse_feed
from libcat.util.text import clean_title


class HarvestService:
    REQUIRED = ("id", "title")

    def __init__(self, repo, on_change=None):
        self.repo = repo
        self.on_change = on_change or (lambda: None)

    def ingest(self, text):
        added, updated, skipped = 0, 0, []
        for fields in parse_feed(text):
            missing = [k for k in self.REQUIRED if not fields.get(k)]
            if missing:
                skipped.append({"id": first(fields.get("id")), "missing": missing})
                continue
            record = self._to_record(fields)
            if self.repo.exists(record.id):
                updated += 1
            else:
                added += 1
            self.repo.save(record)
        if added or updated:
            self.on_change()
        return {"added": added, "updated": updated, "skipped": skipped}

    @staticmethod
    def _to_record(fields):
        return Record(
            id=first(fields["id"]),
            title=clean_title(first(fields["title"])),
            creators=as_list(fields.get("creator")),
            date=fields.get("date"),
            subjects=[s.lower() for s in as_list(fields.get("subject"))],
            language=first(fields.get("language")) or "und",
            publisher=first(fields.get("publisher")) or "",
        )
"""Domain objects."""
from dataclasses import dataclass, field


@dataclass
class Record:
    id: str
    title: str
    creators: list = field(default_factory=list)
    date: object = None          # issued date(s) exactly as delivered by the feed
    subjects: list = field(default_factory=list)
    language: str = "und"
    publisher: str = ""

    def to_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "creators": list(self.creators),
            "date": self.date,
            "subjects": list(self.subjects),
            "language": self.language,
            "publisher": self.publisher,
        }


@dataclass
class Loan:
    record_id: str
    member_id: str
    due_day: int
    returned: bool = False


class NotFound(LookupError):
    pass


class Conflict(RuntimeError):
    pass

